function parseLine(line) {
  const out = [];
  let cur = '';
  let q = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (q) {
      if (c === '"' && line[i + 1] === '"') { cur += '"'; i++; }
      else if (c === '"') q = false;
      else cur += c;
    } else if (c === '"') q = true;
    else if (c === ',') { out.push(cur); cur = ''; }
    else cur += c;
  }
  out.push(cur);
  return out;
}
export function sumColumn(csvText, columnName) {
  const lines = csvText.split(/\r?\n/).filter((l) => l.length);
  const head = parseLine(lines[0]);
  const k = head.indexOf(columnName);
  if (k < 0) throw new Error('no column ' + columnName);
  let s = 0;
  for (const l of lines.slice(1)) {
    const v = Number(parseLine(l)[k]);
    if (Number.isFinite(v)) s += v;
  }
  return s;
}
